package org.jlinalg.cli;

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;
import static org.jlinalg.cli.Monocle3WorkflowRequest.*;

/** Typed unchanged-original selection analysis with owned execution and atomic source/output admission. */
public final class DndscvWorkflowCli {
    private DndscvWorkflowCli() { }
    static final String SCOPE="Original source-bound dndscv selection and optional genesetdnds comparison. Native Java checks complete literal events, explicit reference/coverage choices, coding consequences,192-channel opportunities, exclusions including rank ties, complete N/L arrays, gene counts/expectations, Poisson identities, ordinary BH families and coherent17-digit tables. Optimizers, dNdSloc/dNdScv selection likelihoods, confidence intervals, gene-set fitting and site-level coverage extraction remain upstream; they are not independently refitted. All returned source objects and nonfinite metadata remain. No independent-event provenance, biological calibration, panel/coverage construction, pentanucleotide model, IntOGen consensus or historical paper settings are inferred. Resource limits bound logical work/output, not process RAM or disk quotas. Source functions/data and selected package versions are checked, not every dependency implementation or authenticity.";
    static final String ACTION="Require exit0 and result_admitted=true. Read WARNINGS.md, analysis-status.json, provenance.json, native-event-ledger.tsv, worker-report.json, each source-status.json and original logs. SKIP3: supply the exact permitted Windows R4.6.1/private dependencies and original source profile, or skip dependent analysis. Analysis installs nothing and substitutes no source/version. FAIL2 admits no result from the atomic batch, including earlier successful cases. Preserve inputs, original objects and unadmitted partials; correct the named input/reference/model/capacity/timeout cause and retry NEW paths. Never silently drop events, repair identifiers/alleles, replace NA/NaN/Inf, infer coverage or treat read/spot counts as independent mutation events. P056's reported0.1.0 is not the selected source label0.0.1.0; no paper commit or pentanucleotide equivalence is inferred.";
    private record Captured(Path original,Path copy,NextflowFiles.Pin pin){void verify()throws IOException{require(pin.equals(NextflowFiles.pin(original,pin.bytes(),()->{}))&&pin.equals(NextflowFiles.pin(copy,pin.bytes(),()->{})),"Original/captured input changed: "+original);}}
    public static void main(String[] args){System.exit(run(args,System.out,System.err));}
    public static int run(String[] args,PrintStream output,PrintStream error){
        try{
            if(args.length==1&&args[0].equals("--help")){emit(output,"java -cp DEVELOPMENT.jar org.jlinalg.cli.DndscvWorkflowCli --request request.json\nDeclare schema_version1, mode SELECTION, exact profile, independent_events caller-asserted, genetic_code1, mutations, duplicate_policy, reference, genes, covariates, known_cancer_genes, duplex, analyses, original source, NEW out, rscript, r_home and r_libraries. Mutation headers: sample_id chromosome position reference alternate (tabs). Optional gene_sets is required exactly when a case requests it. No arbitrary scripts/formulas/options or runtime installs. Complete fields/ranges are in DndscvWorkflowRequest.\n"+SCOPE+"\n"+ACTION);return 0;}
            require(args.length==2&&args[0].equals("--request"),"Require --request UTF8_JSON or --help");Path source=Path.of(args[1]).toAbsolutePath().normalize();var sourcePin=NextflowFiles.pin(source,1048576,()->{});byte[] raw=NextflowFiles.bytes(source,1048576);require(raw.length==sourcePin.bytes()&&NextflowFiles.sha(raw).equals(sourcePin.sha256()),"Request changed during intake");var r=DndscvWorkflowRequest.parse(object(NextflowParameters.parse(NextflowFiles.utf8(raw),1048576,100000)),source.getParent());var protectedPaths=new ArrayList<>(r.libraries());protectedPaths.add(r.rHome());protectedPaths.add(r.source());Path out=resolved(r.out());for(Path p:protectedPaths){Path path=resolved(p);require(!out.startsWith(path)&&!path.startsWith(out),"Output cannot overlap original source, R home or libraries, including aliases");}int[] exit={0};
            FollowupSupport.externalTransaction(Map.of("out",r.out().toString()),"original-dndscv-selection-development",(stage,manifest)->{
                var warnings=new ArrayList<String>();warnings.add(SCOPE);warnings.add("BIOLOGICAL INPUT REVIEW: independent events, reference assembly/transcripts/panel and any supplied opportunity/coverage matrix are explicit caller assertions. Native arithmetic and original model execution do not establish their biological validity.");var state=new LinkedHashMap<String,Object>();state.put("status","FAIL2_NO_RESULT_ADMITTED");state.put("result_admitted",false);
                try{
                    verify(source,sourcePin);Files.write(stage.resolve("source-request.json"),raw,StandardOpenOption.CREATE_NEW);NextflowFiles.writeJson(stage.resolve("effective-request.json"),r.effective());Path inputs=Files.createDirectory(stage.resolve("inputs"));var captured=new ArrayList<Captured>();long remaining=r.inputBytes();for(var e:r.inputs().entrySet()){Captured c=capture(e.getValue(),inputs.resolve(e.getKey()),remaining);remaining-=c.pin.bytes();captured.add(c);}var meter=new DndscvWorkflowInputs.Budget(r.auditOperations());var population=DndscvWorkflowInputs.validate(inputs,r,meter);if(!population.duplicateOf().isEmpty())warnings.add("SOURCE DUPLICATE REVIEW: "+population.duplicateOf().size()+" exact input rows follow the explicitly selected source-collapse policy. Every original row remains captured and receives a ledger disposition; recurrence across distinct sample IDs is retained.");
                    var inputPins=new LinkedHashMap<String,Object>();for(Captured c:captured)inputPins.put(c.copy.getFileName().toString(),Map.of("bytes",c.pin.bytes(),"sha256",c.pin.sha256()));manifest.put("source_request_sha256",sourcePin.sha256());manifest.put("captured_inputs",inputPins);Path worker=Files.createDirectory(stage.resolve("worker"));NextflowFiles.writeJson(worker.resolve("parameters.json"),r.parameters());DndscvWorkflowRuntime.sources(stage,r,false);DndscvWorkflowRuntime.run(stage,r,manifest);var original=DndscvWorkflowTransport.read(worker.resolve("worker-report.json"),r);require(text(original.get("status")).equals("completed-with-warnings")&&bool(original.get("source_bodies_and_formals_checked_before_and_after"))&&bool(original.get("source_data_matches_selected_profile")),"Original source/function/data guard incomplete");require(strings(original.get("guarded_functions"),1000).containsAll(List.of("dndscv","genesetdnds","buildref","buildcodon","fitlnpbin","sitednds","codondnds","withingenednds","geneci","geneciloc","getsitedc")),"Original source function guard set incomplete");require(list(original.get("cases")).size()==r.analyses().size(),"Original case population differs");diagnostics(original,warnings,"worker");for(Captured c:captured)c.verify();verify(source,sourcePin);DndscvWorkflowRuntime.sources(stage,r,true);var references=DndscvWorkflowAudit.constructed(worker,population,r,meter);var reports=new ArrayList<Map<String,Object>>();
                    for(var a:r.analyses()){Path home=worker.resolve("cases").resolve(text(a.get("id")));var report=DndscvWorkflowAudit.analysis(home,a,references,population,r,meter);reports.add(report);diagnostics(DndscvWorkflowTransport.read(home.resolve("source-status.json"),r),warnings,text(a.get("id")));long nonfinite=((Number)report.get("nonfinite_original_metadata_fields_retained")).longValue();if(nonfinite>0)warnings.add("ORIGINAL NONFINITE METADATA ["+a.get("id")+"]: "+nonfinite+" fields retained, including any original unbounded confidence limits or unavailable tests. Inspect numeric tokens/kinds and original RDS; no replacement or independent refit occurred.");}
                    long bytes=0;for(long value:CiceroWorkflowRuntime.footprint(worker,r.outputFiles()).values()){require(value<=r.outputBytes()-bytes,"Worker/native audit outputs exceed maximum_output_bytes");bytes+=value;}for(Captured c:captured)c.verify();verify(source,sourcePin);DndscvWorkflowRuntime.sources(stage,r,true);Path results=Files.createDirectory(stage.resolve("results"));for(var a:r.analyses())copyTree(worker.resolve("cases").resolve(text(a.get("id"))),results.resolve(text(a.get("id"))));var provenance=new LinkedHashMap<String,Object>();provenance.put("profile",DndscvWorkflowRequest.PROFILE);provenance.put("source_request_sha256",sourcePin.sha256());provenance.put("captured_inputs",inputPins);provenance.put("native_audit_operations",meter.used);provenance.put("analyses",reports);provenance.put("biological_provenance_or_paper_settings_inferred",false);provenance.put("original_selection_models_independently_refitted",false);NextflowFiles.writeJson(stage.resolve("provenance.json"),provenance);state.put("status","PASS_ORIGINAL_DNDSCV_SELECTION_WORKFLOW");state.put("result_admitted",true);state.put("analyses",reports.size());
                }catch(DndscvWorkflowRuntime.Unavailable failure){exit[0]=3;state.put("status","SKIP3_DEPENDENCY_UNAVAILABLE");state.put("cause",failure.toString());warnings.add("SKIP3 DEPENDENT ANALYSIS SKIPPED: "+failure);quarantine(stage);}
                catch(Exception failure){exit[0]=2;state.put("status","FAIL2_NO_RESULT_ADMITTED");state.put("cause",failure.toString());warnings.add("FAIL2: "+failure);quarantine(stage);}
                catch(OutOfMemoryError failure){exit[0]=2;state.put("status","FAIL2_NO_RESULT_ADMITTED");state.put("cause","Java heap exhausted");warnings.add("FAIL2: Java heap exhausted; retry NEW paths with permitted capacity/heap without dropping events or genes.");quarantine(stage);}
                state.put("required_action",ACTION);NextflowFiles.writeJson(stage.resolve("analysis-status.json"),state);Files.writeString(stage.resolve("WARNINGS.md"),"# "+state.get("status")+"\n\n"+String.join("\n\n",warnings)+"\n\nREQUIRED ACTION: "+ACTION+"\n",StandardCharsets.UTF_8,StandardOpenOption.CREATE_NEW);manifest.put("scope",SCOPE);manifest.put("result_admitted",state.get("result_admitted"));
            });emit(exit[0]==0?output:error,(exit[0]==0?"Original dndscv analysis admitted: ":exit[0]==3?"SKIP3 DEPENDENT ANALYSIS SKIPPED: ":"FAIL2 NO RESULT ADMITTED: ")+r.out());emit(error,"WARNINGS / REQUIRED ACTIONS: "+r.out().resolve("WARNINGS.md")+"\n"+ACTION);return exit[0];
        }catch(Exception failure){emit(error,"FAIL2 NO RESULT ADMITTED: "+failure+"\n"+ACTION);return 2;}
    }
    private static Captured capture(Path original,Path copy,long remaining)throws IOException{require(remaining>=0,"Combined input byte capacity exceeded");var pin=NextflowFiles.pin(original,remaining,()->{});try(var in=Files.newInputStream(original,LinkOption.NOFOLLOW_LINKS);var out=Files.newOutputStream(copy,StandardOpenOption.CREATE_NEW)){byte[] buffer=new byte[65536];long count=0;for(int n=in.read(buffer);n>=0;n=in.read(buffer)){require(n<=remaining-count,"Input grew beyond capacity");out.write(buffer,0,n);count+=n;}require(count==pin.bytes(),"Input changed during capture");}var captured=new Captured(original,copy,pin);captured.verify();return captured;}
    private static void verify(Path source,NextflowFiles.Pin pin)throws IOException{require(pin.equals(NextflowFiles.pin(source,pin.bytes(),()->{})),"Request changed during analysis");}
    private static void diagnostics(Map<String,Object> record,List<String> warnings,String id)throws IOException{for(String field:List.of("warnings","messages"))for(Object raw:list(record.get(field)))warnings.add("ORIGINAL "+field.toUpperCase(Locale.ROOT)+" ["+id+"]: "+text(raw));}
    private static void copyTree(Path from,Path to)throws IOException{require(Files.isDirectory(from,LinkOption.NOFOLLOW_LINKS),"Missing original case outputs");Files.createDirectory(to);try(var paths=Files.walk(from)){for(Path path:paths.toList()){if(path.equals(from))continue;require(!Files.isSymbolicLink(path),"Linked original output refused");Path target=to.resolve(from.relativize(path));if(Files.isDirectory(path,LinkOption.NOFOLLOW_LINKS))Files.createDirectory(target);else{require(Files.isRegularFile(path,LinkOption.NOFOLLOW_LINKS),"Nonregular original output refused");Files.copy(path,target);}}}}
    private static void quarantine(Path stage)throws IOException{Path from=stage.resolve("results").toAbsolutePath().normalize(),to=stage.resolve("unadmitted-partial-results").toAbsolutePath().normalize();require(from.getParent().equals(stage.toAbsolutePath().normalize())&&to.getParent().equals(from.getParent()),"Unsafe result quarantine");if(Files.exists(from))Files.move(from,to);}
    private static Path resolved(Path path)throws IOException{var missing=new ArrayDeque<Path>();Path current=path.toAbsolutePath().normalize();while(!Files.exists(current,LinkOption.NOFOLLOW_LINKS)){require(current.getParent()!=null,"No existing path ancestor");missing.addFirst(current.getFileName());current=current.getParent();}current=current.toRealPath();for(Path name:missing)current=current.resolve(name);return current.normalize();}
    private static void emit(PrintStream stream,String value){byte[] raw=(value+"\n").getBytes(StandardCharsets.UTF_8);stream.write(raw,0,raw.length);stream.flush();}
}
